use std::collections::{BTreeMap, HashMap, VecDeque};
use std::io::{self, BufRead, BufWriter, Stdout, Write};

#[derive(Clone, Copy, PartialEq, Eq)]
enum Side {
    Buy,
    Sell,
}

impl Side {
    fn opposite(self) -> Side {
        match self {
            Side::Buy => Side::Sell,
            Side::Sell => Side::Buy,
        }
    }
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum Kind {
    Gtc,
    Ioc,
    Fok,
}

struct Resting {
    trader: String,
    side: Side,
    price: u64,
    rem: u64,
}

struct Book {
    orders: HashMap<u64, Resting>,
    bids: BTreeMap<u64, VecDeque<u64>>,
    asks: BTreeMap<u64, VecDeque<u64>>,
    positions: BTreeMap<String, (i64, i64)>,
    next_id: u64,
    out: BufWriter<Stdout>,
    failed: bool,
}

/// Digits only, value within [lo, hi].
fn number(s: &str, lo: u64, hi: u64) -> Option<u64> {
    if s.is_empty() || !s.bytes().all(|b| b.is_ascii_digit()) {
        return None;
    }
    let v: u64 = s.parse().ok()?;
    (lo..=hi).contains(&v).then_some(v)
}

fn qty(s: &str) -> Option<u64> {
    number(s, 1, 1_000_000)
}

fn price(s: &str) -> Option<u64> {
    number(s, 1, 100_000)
}

fn order_id(s: &str) -> Option<u64> {
    if s.len() > 7 {
        return None;
    }
    number(s, 1, 9_999_999)
}

type Order<'a> = (Side, &'a str, u64, Option<u64>, Kind);

fn parse_order<'a>(f: &[&'a str]) -> Option<Order<'a>> {
    let side = match *f.first()? {
        "buy" | "mbuy" => Side::Buy,
        "sell" | "msell" => Side::Sell,
        _ => return None,
    };
    let market = f[0].starts_with('m');
    match f {
        [_, t, q] if market => Some((side, *t, qty(q)?, None, Kind::Ioc)),
        [_, t, q, p] if !market => Some((side, *t, qty(q)?, Some(price(p)?), Kind::Gtc)),
        [_, t, q, p, k] if !market => {
            let kind = match *k {
                "ioc" => Kind::Ioc,
                "fok" => Kind::Fok,
                _ => return None,
            };
            Some((side, *t, qty(q)?, Some(price(p)?), kind))
        }
        _ => None,
    }
}

/// Whether a resting order at `price` trades with an incoming `side` order with `limit`.
fn crosses(side: Side, price: u64, limit: Option<u64>) -> bool {
    match limit {
        None => true,
        Some(l) => {
            if side == Side::Buy {
                price <= l
            } else {
                price >= l
            }
        }
    }
}

impl Book {
    fn new() -> Self {
        Book {
            orders: HashMap::new(),
            bids: BTreeMap::new(),
            asks: BTreeMap::new(),
            positions: BTreeMap::new(),
            next_id: 1,
            out: BufWriter::new(io::stdout()),
            failed: false,
        }
    }

    fn emit(&mut self, s: String) {
        let _ = writeln!(self.out, "{s}");
    }

    fn error(&mut self, msg: String) {
        self.emit(msg);
        self.failed = true;
    }

    fn bad(&mut self) {
        self.error("error: bad command".into());
    }

    fn levels(&self, side: Side) -> &BTreeMap<u64, VecDeque<u64>> {
        match side {
            Side::Buy => &self.bids,
            Side::Sell => &self.asks,
        }
    }

    fn levels_mut(&mut self, side: Side) -> &mut BTreeMap<u64, VecDeque<u64>> {
        match side {
            Side::Buy => &mut self.bids,
            Side::Sell => &mut self.asks,
        }
    }

    fn command(&mut self, f: &[&str]) {
        if f.iter().any(|s| s.is_empty()) {
            return self.bad();
        }
        match f {
            ["book"] => self.print_book(),
            ["pos"] => self.print_pos(),
            ["cancel", t, id] => match order_id(id) {
                Some(id) => self.cancel(t, id),
                None => self.bad(),
            },
            ["amend", t, id, q] => match (order_id(id), qty(q)) {
                (Some(id), Some(q)) => self.amend(t, id, q),
                _ => self.bad(),
            },
            _ => match parse_order(f) {
                Some((side, t, q, p, kind)) => self.submit(side, t, q, p, kind),
                None => self.bad(),
            },
        }
    }

    fn adjust(&mut self, trader: &str, dqty: i64, dcash: i64) {
        let e = self
            .positions
            .entry(trader.to_string())
            .or_insert((0, 0));
        e.0 += dqty;
        e.1 += dcash;
    }

    /// Best price on the `side.opposite()` book that crosses an incoming `side` order.
    fn best(&self, side: Side, limit: Option<u64>) -> Option<u64> {
        let levels = self.levels(side.opposite());
        let p = if side == Side::Buy {
            levels.keys().next()
        } else {
            levels.keys().next_back()
        }?;
        let p = *p;
        crosses(side, p, limit).then_some(p)
    }

    /// Quantity of other traders' resting orders that cross the limit.
    fn fillable(&self, side: Side, trader: &str, limit: Option<u64>) -> u64 {
        let mut total = 0;
        for (&p, queue) in self.levels(side.opposite()) {
            if !crosses(side, p, limit) {
                continue;
            }
            for rid in queue {
                let r = &self.orders[rid];
                if r.trader != trader {
                    total += r.rem;
                }
            }
        }
        total
    }

    fn pop_front(&mut self, side: Side, price: u64) {
        let levels = self.levels_mut(side);
        let queue = levels.get_mut(&price).expect("level exists");
        queue.pop_front();
        if queue.is_empty() {
            levels.remove(&price);
        }
    }

    fn submit(&mut self, side: Side, trader: &str, qty: u64, limit: Option<u64>, kind: Kind) {
        let id = self.next_id;
        self.next_id += 1;
        self.positions.entry(trader.to_string()).or_insert((0, 0));
        self.emit(format!("order {id}"));

        if kind == Kind::Fok && self.fillable(side, trader, limit) < qty {
            self.emit(format!("reject {id} fok"));
            return;
        }

        let opp = side.opposite();
        let mut left = qty;
        while left > 0 {
            let Some(price) = self.best(side, limit) else {
                break;
            };
            let rid = *self.levels(opp)[&price].front().expect("non-empty level");
            let rtrader = self.orders[&rid].trader.clone();
            if rtrader == trader {
                self.pop_front(opp, price);
                self.orders.remove(&rid);
                self.emit(format!("cancel {rid} self-trade"));
                continue;
            }

            let rrem = self.orders[&rid].rem;
            let q = left.min(rrem);
            let (buy_id, sell_id) = if side == Side::Buy { (id, rid) } else { (rid, id) };
            self.emit(format!("trade {buy_id} {sell_id} {q} @ {price}"));

            let cash = (q * price) as i64;
            let q = q as i64;
            if side == Side::Buy {
                self.adjust(trader, q, -cash);
                self.adjust(&rtrader, -q, cash);
            } else {
                self.adjust(&rtrader, q, -cash);
                self.adjust(trader, -q, cash);
            }

            if rrem == q as u64 {
                self.pop_front(opp, price);
                self.orders.remove(&rid);
            } else {
                self.orders.get_mut(&rid).expect("resting order").rem -= q as u64;
            }
            left -= q as u64;
        }

        if left > 0 {
            match (kind, limit) {
                (Kind::Gtc, Some(p)) => {
                    self.levels_mut(side).entry(p).or_default().push_back(id);
                    self.orders.insert(
                        id,
                        Resting {
                            trader: trader.to_string(),
                            side,
                            price: p,
                            rem: left,
                        },
                    );
                    self.emit(format!("rest {id} {left}"));
                }
                _ => self.emit(format!("drop {id} {left}")),
            }
        }
    }

    /// Looks up a resting order that belongs to `trader`: (side, price, remaining).
    fn owned(&self, trader: &str, id: u64) -> Result<(Side, u64, u64), String> {
        let r = self
            .orders
            .get(&id)
            .ok_or(format!("error: no such order {id}"))?;
        if r.trader != trader {
            return Err("error: not owner".into());
        }
        Ok((r.side, r.price, r.rem))
    }

    fn cancel(&mut self, trader: &str, id: u64) {
        match self.owned(trader, id) {
            Err(e) => self.error(e),
            Ok((side, price, rem)) => {
                let levels = self.levels_mut(side);
                if let Some(queue) = levels.get_mut(&price) {
                    queue.retain(|&x| x != id);
                    if queue.is_empty() {
                        levels.remove(&price);
                    }
                }
                self.orders.remove(&id);
                self.emit(format!("cancelled {id} {rem}"));
            }
        }
    }

    fn amend(&mut self, trader: &str, id: u64, new_qty: u64) {
        match self.owned(trader, id) {
            Err(e) => self.error(e),
            Ok((side, price, rem)) => {
                if new_qty > rem {
                    let queue = self
                        .levels_mut(side)
                        .get_mut(&price)
                        .expect("level exists");
                    queue.retain(|&x| x != id);
                    queue.push_back(id);
                }
                self.orders.get_mut(&id).expect("resting order").rem = new_qty;
                self.emit(format!("amended {id} {new_qty}"));
            }
        }
    }

    fn level_lines(&self, side: Side) -> Vec<String> {
        let mut lines: Vec<String> = self
            .levels(side)
            .iter()
            .rev()
            .map(|(p, queue)| {
                let total: u64 = queue.iter().map(|id| self.orders[id].rem).sum();
                format!("  {p} {total} {}", queue.len())
            })
            .collect();
        if lines.is_empty() {
            lines.push("  (none)".into());
        }
        lines
    }

    fn print_book(&mut self) {
        let mut lines = vec!["asks:".to_string()];
        lines.extend(self.level_lines(Side::Sell));
        lines.push("bids:".to_string());
        lines.extend(self.level_lines(Side::Buy));
        for l in lines {
            self.emit(l);
        }
    }

    fn print_pos(&mut self) {
        if self.positions.is_empty() {
            self.emit("(no traders)".into());
            return;
        }
        let lines: Vec<String> = self
            .positions
            .iter()
            .map(|(name, (q, c))| format!("{name} {q} {c}"))
            .collect();
        for l in lines {
            self.emit(l);
        }
    }
}

fn main() {
    let mut book = Book::new();
    for line in io::stdin().lock().lines() {
        let Ok(line) = line else { break };
        let t = line.trim();
        if t.is_empty() {
            continue;
        }
        let f: Vec<&str> = t.split(' ').collect();
        book.command(&f);
    }
    let _ = book.out.flush();
    if book.failed {
        std::process::exit(1);
    }
}

